#include "symrep_bootstrap.hpp"
#include <unordered_map>
using namespace symrep;using Word=uint64_t;
static Word encode(const std::vector<size_t>&w,size_t omit=SIZE_MAX){Word x=0;for(size_t k=0;k<w.size();++k)if(k!=omit)x=88*x+w[k];return x;}
int main(int argc,char**argv){try{require(argc==5,"usage affine_tail_origin OUT source_Fn_word.wxf dual_words.txt stem");fs::path out=argv[1];std::string stem=argv[4];auto start=std::chrono::steady_clock::now();auto f=read(argv[2]);size_t w=f.rank(),source_nnz=f.nnz();require(w==4||w==6,"source weight must be4or6");std::unordered_map<Word,Vec> deriv;deriv.reserve(f.nnz()/5);for(size_t first=0;first<f.dim(0);++first)for(size_t p=f.rowptr()[first];p<f.rowptr()[first+1];++p){auto idx=f.index(p);Word key=first;for(size_t j=0;j<w-2;++j)key=88*key+idx[j];deriv[key].push_back(idx[w-2],f.val(p));}f.clear();for(auto&[_,v]:deriv)normalize(v);
 auto E=read_matrix(out/"lastpair_E.wxf"),L=read_matrix(out/"lastpair_rightinverse.wxf");std::ifstream cfg(out/"affine_tail_static.txt");size_t n;cfg>>n;require(n==83,"pivotcount");std::vector<size_t>piv(n);for(auto&v:piv){cfg>>v;--v;}size_t np;cfg>>np;Mat P(88,76);for(size_t k=0;k<np;++k){size_t a,b;std::string x;cfg>>a>>b>>x;P[a-1].push_back(index(b-1),Q(x));}for(auto&row:P.rows)normalize(row);require(bool(cfg),"staticinputparse");
 std::ifstream inp(argv[3]);size_t count,weight;inp>>count>>weight;require(weight==w,"dualweight");Mat src(count,83),origin(count,175);size_t fullnnz=0;std::cout<<"INPUT source_words="<<source_nnz<<" derivative_contexts="<<deriv.size()<<" prefix_count="<<count<<" seconds="<<seconds(start)<<std::endl;
 for(size_t r=0;r<count;++r){std::vector<size_t>q(w);for(auto&x:q){inp>>x;--x;}std::string scale;inp>>scale;Q den(scale);require(den!=0&&bool(inp),"dualparse");std::map<I,Q>h;
  auto base=deriv.find(encode(q,w-1));if(base!=deriv.end())for(auto[a,x]:base->second)if(size_t(a)==q.back())for(size_t t=0;t<88;++t)for(auto[j,y]:P[t])h[index(76*t+j)]+=x*y;
  for(size_t k=0;k<w;++k)if(P[q[k]].nnz()){auto d=deriv.find(encode(q,k));if(d!=deriv.end())for(auto[t,x]:d->second)for(auto[j,y]:P[q[k]])h[index(76*t+j)]+=x*y;}
  for(auto&[_,x]:h)x/=den;auto full=packed(h);fullnnz+=full.nnz();for(size_t j=0;j<83;++j){auto it=h.find(index(piv[j]));if(it!=h.end()&&it->second!=0)src[r].push_back(index(j),it->second);}origin[r]=mul(src[r],L);auto check=mul(origin[r],E);require(check.nnz()==full.nnz(),"localtailresidualsupport row"+std::to_string(r));for(size_t j=0;j<full.nnz();++j)require(check(j)==full(j)&&check[j]==full[j],"localtailresidual row"+std::to_string(r));
 }
 write(out/(stem+"_pivot_source.wxf"),src);write(out/(stem+"_TF175_origin.wxf"),origin);std::ofstream receipt(out/(stem+".json"));receipt<<"{\"prefix_weight\":"<<w<<",\"prefix_dimension\":"<<count<<",\"source_words\":"<<source_nnz<<",\"derivative_contexts\":"<<deriv.size()<<",\"pivot_source_nonzeros\":"<<src.nnz()<<",\"origin_nonzeros\":"<<origin.nnz()<<",\"full_tail_source_nonzeros\":"<<fullnnz<<",\"all_full_local_tail_residuals_exact_zero\":true,\"source_coordinates\":\"Complete actual-word dual chart, with structural membership from universal log insertion theorem; every full6688-component local tail lift checked overQ.\",\"scope\":\"Particular solution of affine remainder-tail equations in FECw tensor LEC2(TF15). Global seam, symmetry, and boundary regularity still required.\",\"F4_target_read\":false,\"seconds\":"<<seconds(start)<<"}\n";std::cout<<"COMPLETE prefix="<<count<<" origin_nnz="<<origin.nnz()<<" source_nnz="<<fullnnz<<" local_residuals_pass=1 seconds="<<seconds(start)<<std::endl;
 }catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
